package org.springframework.samples.petclinic.rest.controller.v1;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Collection;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Households are keyed deterministically on (normalized last name, postcode): every owner carries
 * the household id derived from those two fields, so owners that share them belong to the same
 * household automatically. {@code sharesHousehold} no longer creates the link (the id is always
 * computed); it only lets a further member of an existing household bypass the duplicate block.
 */
final class HouseholdDuplicates {

    private HouseholdDuplicates() {
    }

    /**
     * Stamps {@code candidate} with its deterministic household id (first 12 hex characters of
     * SHA-256 over {@code normalizedLastName + '|' + postcode}).
     */
    static void assignHousehold(Owner candidate, Collection<Owner> existing, Boolean sharesHousehold) {
        candidate.setHouseholdId(householdId(candidate));
    }

    /**
     * Returns {@code true} when an existing owner already belongs to {@code candidate}'s household
     * and the request did not opt in via {@code sharesHousehold}.
     */
    static boolean isRejectedDuplicate(Owner candidate, Collection<Owner> existing, Boolean sharesHousehold) {
        if (Boolean.TRUE.equals(sharesHousehold)) {
            return false;
        }
        String id = householdId(candidate);
        return existing.stream().anyMatch(other -> id.equals(householdId(other)));
    }

    /** First 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. */
    static String householdId(Owner owner) {
        String key = norm(owner.getLastName()) + "|" + blank(owner.getPostcode());
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (Exception e) {
            throw new IllegalStateException(e);
        }
    }

    private static String blank(String value) {
        return value == null ? "" : value;
    }

    private static String norm(String value) {
        return value == null ? "" : value.replaceAll("\\s+", " ").trim().toLowerCase();
    }
}

package org.springframework.samples.petclinic.rest.controller.v1;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Collection;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of duplicate detection: an owner's identity is the SHA-256 hex of
 * {@code normalizedTelephone|lowerEmail|soundex(lastName)} (email empty when absent). Two owners
 * collide only when their whole keys are equal, so members of one household (same last name and
 * postcode) with different telephones stay distinct and surface only as soft matches.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    /** The derived identity key of {@code owner}; telephone is already E.164-normalized upstream. */
    public static String of(Owner owner) {
        String raw = blank(owner.getTelephone()) + "|" + lower(owner.getEmail()) + "|"
            + Soundex.code(owner.getLastName());
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (Exception e) {
            throw new IllegalStateException(e);
        }
    }

    /** {@code true} when an existing owner has the exact same identity key as {@code candidate}. */
    static boolean isDuplicate(Owner candidate, Collection<Owner> existing) {
        String key = of(candidate);
        return existing.stream().anyMatch(other -> of(other).equals(key));
    }

    private static String blank(String value) {
        return value == null ? "" : value;
    }

    private static String lower(String value) {
        return value == null ? "" : value.toLowerCase();
    }
}

package org.springframework.samples.petclinic.model;

import java.util.concurrent.atomic.AtomicLong;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import jakarta.persistence.PostPersist;

/**
 * Emits an audit trail entry via the dedicated {@code AUDIT} logger whenever a new
 * owner is persisted, carrying the owner id, customer code and registration date.
 */
public class OwnerAuditListener {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");

    private static final AtomicLong SEQ = new AtomicLong();

    @PostPersist
    void onCreate(Owner owner) {
        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
            org.springframework.samples.petclinic.rest.controller.v1.MembershipLevel.of(owner));
        AUDIT.info(String.format(
            "{\"seq\":%d,\"ownerId\":%d,\"memberId\":\"%s\",\"membershipLevel\":%d,\"event\":\"OWNER_CREATED\"}",
            SEQ.incrementAndGet(), owner.getId(), owner.getMemberId(),
            org.springframework.samples.petclinic.rest.controller.v1.MembershipLevel.of(owner)));
        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
    }
}
